insert into public.aides (id, organisme, region, portee, departements, programme, type_projet, beneficiaires, description, montant_resume, montant_max_eur, statut, actif, prochaine_date_limite, calendrier, conditions_cles, pieces_a_fournir, mode_depot, url_officielle, url_page_regionale, url_conditions_pdf, url_monprojetmusique, date_derniere_verification, verifie_par, prochaine_verification, notes) values
  ('ADA-001', 'Adami', 'National', 'National', '{}'::text[], 'Bourse Parcours Artiste', 'Développement de carrière', 'Artiste-interprète associé de l''Adami (toutes esthétiques)', 'Soutien direct pour passer un cap dans la carrière, sans lien avec un projet artistique.', 'Plafond 4 000 €, dépenses minimum 1 500 €. Imposable en BNC.', 4000, 'Permanent', true, null, 'Dépôt au moins 2 mois avant la 1re dépense. Commission ~toutes les 6 semaines (sauf juillet-août).', 'Être associé Adami.', 'Pièces listées dans le PDF « conditions d''accès ». Dossier incomplet bloqué à la saisie.', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/bourse-parcours-artiste/', null, 'https://www.adami.fr/wp-content/uploads/2026/03/BourseParcoursArtiste-Conditions-mars2026.pdf', 'https://www.monprojetmusique.fr/aides/bourse-parcours-artiste/', '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('ADA-002', 'Adami', 'National', 'National', '{}'::text[], 'Aide à la production d''un enregistrement et sa promotion', 'Production phonographique', 'Artiste-producteur', 'Enregistrement (EP/album) associé à un outil audiovisuel (documentaire > 5 min, clip, captation).', 'Enregistrement plafonné à 15 000 € (20 000 € si > 20 artistes salariés) + forfait audiovisuel 2 500 € + forfait promotion 2 500 €. Bonus égalité F/H +20 %.', 20000, 'Permanent', true, null, 'Dépôt au moins 3 mois avant la 1re sortie commerciale. Commission Musique ~toutes les 6 semaines.', 'Projet audiovisuel obligatoire. Bonus égalité à demander dès le dépôt.', 'Pièces listées dans le PDF « conditions d''accès ». Dossier incomplet bloqué à la saisie.', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/aide-production-enregistrement-promotion/', null, 'https://www.adami.fr/wp-content/uploads/2026/05/Adami-2D3D-procedure-conditions_05-2026.pdf', 'https://www.monprojetmusique.fr/aides/aide-a-la-production-dun-enregistrement-et-sa-promotion/', '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('ADA-003', 'Adami', 'National', 'National', '{}'::text[], 'Aide à la promotion d''un enregistrement', 'Promotion / Médiatisation', 'Artiste-interprète (structure d''artiste)', 'Financer la promotion d''un EP ou d''un album (communication, marketing).', 'Plafond 8 000 €. En coproduction avec une structure non-artiste : 40 % des dépenses HT max.', 8000, 'Permanent', true, null, 'Dépôt avant la 1re sortie commerciale. Commission Musique ~toutes les 6 semaines.', null, 'Pièces listées dans le PDF « conditions d''accès ». Dossier incomplet bloqué à la saisie.', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/aide-promotion-enregistrement/', null, 'https://www.adami.fr/wp-content/uploads/2026/05/Adami_conditions_aide-promotion_05-2026.pdf', 'https://www.monprojetmusique.fr/aides/aide-a-la-promotion-dun-enregistrement/', '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('ADA-004', 'Adami', 'National', 'National', '{}'::text[], 'Aide pour un spectacle de musique', 'Production scénique', 'Producteur de spectacle (employeur du plateau)', 'Soutien à l''emploi des artistes-interprètes pour une création ou la diffusion d''un spectacle déjà joué 3 fois. Tous genres.', 'Calcul plafonné à 150 €/service, 300 €/cachet ou 3 000 €/mois (bruts). Plafond global 20 000 €.', 20000, 'Permanent', true, null, 'Au plus tôt 4 mois avant la 1re représentation, au plus tard le jour de la 1re représentation.', 'Au moins 3 artistes salariés par représentation, nombre minimum de dates. Contrôles mensuels.', 'Lettres ou courriels d''engagement ferme de l''organisateur (salle, date). Pièces du PDF conditions.', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/aide-spectacle-musique/', null, 'https://www.adami.fr/wp-content/uploads/2025/10/Adami_conditions_aide-spectacle_10-2025-1.pdf', 'https://www.monprojetmusique.fr/aides/aide-pour-un-spectacle-de-musique/', '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', 'Aide simplifiée (APA).'),
  ('ADA-005', 'Adami', 'National', 'National', '{}'::text[], 'Aide au projet musical global (Adami 365)', 'Projet global (disque + scène + promo + audiovisuel)', 'Artiste-producteur identifié', 'Projet exceptionnel sur 12 mois : enregistrement obligatoire + au moins 2 volets parmi spectacle, promotion, audiovisuel.', 'Montant selon les volets (détail dans le PDF conditions).', null, 'Permanent (sur contact)', true, null, 'Contacter directement l''Adami. Passage en commission Musique.', 'Au moins 3 volets dont l''enregistrement.', 'Pièces listées dans le PDF « conditions d''accès ». Dossier incomplet bloqué à la saisie.', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/projet-musical-global/', null, 'https://www.adami.fr/wp-content/uploads/2026/05/Adami-365-procedure-conditions_05-2026.pdf', 'https://www.monprojetmusique.fr/aides/aide-au-projet-musical-global/', '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('ADA-006', 'Adami', 'National', 'National', '{}'::text[], 'Aide première partie musique', 'Diffusion', 'Producteur de spectacle', 'Finance la rémunération des artistes en première partie de concert.', '70 % des salaires bruts + forfait 250 €/représentation. Plafond 6 000 €.', 6000, 'Permanent', true, null, 'Au plus tôt 4 mois avant, au plus tard le jour de la 1re représentation. Acceptation automatique 1 mois après dépôt.', 'Respect de la grille de critères et des délais.', 'Lettres ou courriels d''engagement ferme (salle, date, conditions financières).', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/aide-premiere-partie-musique/', null, 'https://www.adami.fr/wp-content/uploads/2025/10/Adami_conditions_aide-1ere-partie-musique_10-2025-1.pdf', 'https://www.monprojetmusique.fr/aides/aide-premiere-partie/', '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', 'Aide simplifiée (APA).'),
  ('ADA-007', 'Adami', 'National', 'National', '{}'::text[], 'Adami Déclencheur – théâtre, marionnettes, cirque', 'Création (3 phases)', 'Comédien·ne associé·e Adami (≥ 1 500 € de droits Adami sur 5 ans)', 'Programme en 3 phases : bourse d''écriture/développement, production, diffusion.', 'Phase 1 bourse 2 000 à 5 000 € ; phase 2 12 000 € + 100 €/artiste/cachet ; phase 3 6 000 €. Cumul max 45 000 €.', 45000, 'Permanent', true, null, 'En continu. Commission artistique environ toutes les 6 semaines (pas en juillet-août), réponse le jour de la commission.', '2 fois max par artiste, 5 ans entre deux aides.', 'Pièces listées dans le PDF « conditions d''accès ». Dossier incomplet bloqué à la saisie.', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/aide-projet-theatre-marionnettes-cirque/', null, 'https://www.adami.fr/wp-content/uploads/2025/10/Adami_conditions_aide-declencheur-TH_10-2025-1.pdf', null, '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('ADA-008', 'Adami', 'National', 'National', '{}'::text[], 'Aide pour un spectacle de théâtre', 'Production scénique', 'Producteur de spectacle', 'Emploi des artistes-interprètes pour un spectacle de théâtre (création ou reprise).', '150 €/service, 300 €/cachet ou 3 000 €/mois (bruts). Plafond 20 000 €.', 20000, 'Permanent', true, null, 'Au plus tôt 4 mois avant, au plus tard le jour de la 1re représentation.', 'Nombre minimum de représentations sur 9 mois max.', 'Lettres ou courriels d''engagement ferme (salle, date, conditions financières).', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/aide-spectacle-theatre/', null, 'https://www.adami.fr/wp-content/uploads/2025/10/Adami_conditions_aide-spectacle_10-2025-1.pdf', null, '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('ADA-009', 'Adami', 'National', 'National', '{}'::text[], 'Aide pour un spectacle de danse', 'Production scénique', 'Producteur de spectacle', 'Emploi des artistes-interprètes pour un spectacle de danse.', '150 €/service, 300 €/cachet ou 3 000 €/mois (bruts). Plafond 20 000 €.', 20000, 'Permanent', true, null, 'Au plus tôt 4 mois avant, au plus tard le jour de la 1re représentation.', '≥ 3 artistes salariés par représentation, ≥ 4 représentations confirmées sur 9 mois.', 'Lettres ou courriels d''engagement ferme (salle, date, conditions financières).', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/aide-spectacle-danse/', null, 'https://www.adami.fr/wp-content/uploads/2025/10/Adami_conditions_aide-spectacle_10-2025-1.pdf', null, '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('ADA-010', 'Adami', 'National', 'National', '{}'::text[], 'Adami Déclencheur – création audiovisuelle', 'Audiovisuel (3 phases)', 'Comédien·ne associé·e Adami (≥ 1 500 € de droits Adami sur 5 ans)', 'Bourse de développement, aide à la production, aide à la diffusion d''un projet audiovisuel.', 'Bourse 3 000 € max ; production 80 % des rémunérations (450 €/jour/artiste max) + forfait 20 000 € ; diffusion 3 000 €. Cumul max 45 000 €.', 45000, 'Permanent', true, null, 'En continu. Commission artistique environ toutes les 6 semaines (pas en juillet-août), réponse le jour de la commission.', '2 fois max par artiste, 5 ans entre deux aides.', 'Pièces listées dans le PDF « conditions d''accès ». Dossier incomplet bloqué à la saisie.', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/aide-projet-creation-audiovisuelle/', null, 'https://www.adami.fr/wp-content/uploads/2026/04/Adami_conditions_aide-declencheur-AV_04-2026.pdf', null, '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('ADA-011', 'Adami', 'National', 'National', '{}'::text[], 'Bourse / Aide première fois – audiovisuel', 'Audiovisuel', 'Artiste-interprète (1er projet)', 'Bourse pour un premier projet audiovisuel.', 'Bourse de 5 000 € max.', 5000, 'Permanent', true, null, 'Dépôt au plus tard 2 mois avant les premiers frais. Commission Théâtre-audiovisuel-danse ~toutes les 6 semaines.', null, 'Pièces listées dans le PDF « conditions d''accès ». Dossier incomplet bloqué à la saisie.', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/bourse-premiere-fois-audiovisuel/', null, 'https://www.adami.fr/wp-content/uploads/2025/10/Adami_conditions_bourse-1ere-fois_audiovisuel_10-2025-1.pdf', null, '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('ADA-012', 'Adami', 'National', 'National', '{}'::text[], 'Bourse / Aide première fois – théâtre et danse', 'Création', 'Artiste-interprète (1er projet)', 'Bourse pour un premier projet de théâtre ou de danse.', 'Bourse de 5 000 € max.', 5000, 'Permanent', true, null, 'Dépôt au plus tard 2 mois avant les premiers frais. Commission Théâtre-audiovisuel-danse ~toutes les 6 semaines.', null, 'Pièces listées dans le PDF « conditions d''accès ». Dossier incomplet bloqué à la saisie.', 'Compte Adami > « Aides sélectives (i-DA) » ou « Aides simplifiées (APA) »', 'https://www.adami.fr/que-fait-ladami-pour-moi/cherche-financement-projet-artistique/bourse-premiere-fois-theatre-danse/', null, 'https://www.adami.fr/wp-content/uploads/2025/10/Adami_conditions_bourse-1ere-fois_theatre-et-danse_10-2025-1.pdf', null, '2026-11-21', 'Claude (lecture du site officiel)', '2027-01-15', null),
  ('SPE-001', 'Spedidam', 'National', 'National', '{}'::text[], 'Aide au spectacle musical', 'Production / diffusion scénique', 'Producteur de spectacle (employeur des artistes)', 'Création/diffusion de spectacle vivant musical. Aide sur la masse salariale des artistes-interprètes.', 'Max 40 % du coût employeur des artistes (minimum 6 000 € de coût employeur). Cachets pris en compte plafonnés à 250 € (répétition) / 500 € (représentation).', null, 'Ouvert (commission janv. 2027)', true, '2026-12-21', 'Commissions mensuelles (voir onglet Calendrier). Prochaine : 25-29 janv. 2027, dépôt avant le 21/12/2026 inclus.', '≥ 6 représentations sur 5 jours (4 jours si ≥ 8 artistes), max 10 répétitions. Minimums 120 €/répétition, 175 €/cachet. Dates postérieures à la commission. Logo Spedidam.', 'Dossier complet sur ADEL + contrat signé pour une date ferme postérieure à la commission. Solde du dossier précédent demandé avant tout nouveau dépôt.', 'Espace ADEL (adel.spedidam.fr)', 'https://www.spedidam.fr/aides-aux-projets/nos-programmes/aide-au-spectacle-musical/', null, null, 'https://www.monprojetmusique.fr/aides/spectacle-vivant-hors-spectacle-dramatique-choregraphique-de-cirque-de-marionnettes-revue-cabaret-music-hall-et-sons-et-lumieres/', '2026-11-21', 'Claude (lecture du site officiel)', '2026-12-21', null),
  ('SPE-002', 'Spedidam', 'National', 'National', '{}'::text[], 'Aide au spectacle dramatique, chorégraphique, cirque, marionnette', 'Production / diffusion scénique', 'Producteur de spectacle', 'Spectacle vivant hors musical (théâtre, danse, cirque, variétés, cabaret...). Aide sur la masse salariale des artistes.', 'Max 30 % du coût employeur (minimum 6 000 €). Cachets pris en compte plafonnés à 250 € / 500 €.', null, 'Ouvert (commission janv. 2027)', true, '2026-12-21', 'Commissions mensuelles (voir onglet Calendrier). Prochaine : 25-29 janv. 2027, dépôt avant le 21/12/2026 inclus.', 'Représentations sur ≥ 8 jours, max 20 répétitions. Minimums de rémunération selon grille.', 'Dossier complet sur ADEL + contrat signé pour une date ferme postérieure à la commission. Solde du dossier précédent demandé avant tout nouveau dépôt.', 'Espace ADEL (adel.spedidam.fr)', 'https://www.spedidam.fr/aides-aux-projets/nos-programmes/aide-au-spectacle-dramatique-choregraphique-cirque-marionnette/', null, null, 'https://www.monprojetmusique.fr/aides/spectacle-dramatique-choregraphique-ou-cirque-varietes-marionnettes-revues-cabaret-music-hall-et-sons-et-lumieres/', '2026-11-21', 'Claude (lecture du site officiel)', '2026-12-21', null),
  ('SPE-003', 'Spedidam', 'National', 'National', '{}'::text[], 'Aide aux festivals', 'Festival', 'Organisateur de festival de musique ou de chanson', 'Masse salariale des artistes-interprètes d''un festival de musique/chanson (hors théâtre et danse).', 'Max 40 % du coût employeur. Cachet pris en compte plafonné à 500 €.', null, 'Ouvert (commission janv. 2027)', true, '2026-12-21', 'Commissions mensuelles (voir onglet Calendrier). Prochaine : 25-29 janv. 2027, dépôt avant le 21/12/2026 inclus.', '≥ 6 représentations sur ≥ 3 jours, durée max 31 jours. Cachet minimum 175 €. Projet débutant au plus tard 6 mois après la commission.', 'Dossier complet sur ADEL + contrat signé pour une date ferme postérieure à la commission. Solde du dossier précédent demandé avant tout nouveau dépôt.', 'Espace ADEL (adel.spedidam.fr)', 'https://www.spedidam.fr/aides-aux-projets/nos-programmes/aide-aux-festivals/', null, null, 'https://www.monprojetmusique.fr/aides/musique-ou-chanson/', '2026-11-21', 'Claude (lecture du site officiel)', '2026-12-21', null),
  ('SPE-004', 'Spedidam', 'National', 'National', '{}'::text[], 'Aide au déplacement à l''international', 'Export / tournée', 'Structure employeuse d''artistes-interprètes', 'Frais de déplacement d''artistes pour des représentations hors de France (et DROM-COM ↔ métropole).', 'Max 65 % des billets (80 % DROM-COM). Plafond 750 €/pers. en Europe, 1 500 €/pers. ailleurs, 15 artistes max.', null, 'Ouvert (commission janv. 2027)', true, '2026-12-21', 'Commissions mensuelles (voir onglet Calendrier). Prochaine : 25-29 janv. 2027, dépôt avant le 21/12/2026 inclus.', '≥ 3 dates dans ≥ 3 lieux différents, déplacement après la commission et au plus tard 6 mois après.', '3 lettres d''invitation signées de 3 lieux différents à l''étranger (courriels refusés). Pas plus de 2 aides non soldées.', 'Espace ADEL (adel.spedidam.fr)', 'https://www.spedidam.fr/aides-aux-projets/nos-programmes/aide-au-deplacement-a-linternational/', null, null, 'https://www.monprojetmusique.fr/aides/deplacement-international/', '2026-11-21', 'Claude (lecture du site officiel)', '2026-12-21', null),
  ('SPE-005', 'Spedidam', 'National', 'National', '{}'::text[], 'Aide à la création d''une bande originale pour spectacle dramatique ou chorégraphique', 'Création musicale', 'Producteur de spectacle', 'Création et enregistrement d''une BO (≥ 20 min ou 1/3 du spectacle) pour théâtre, danse, cirque, etc.', 'Max 60 % (coût employeur des musiciens + commande). Commande prise en compte 3 000 € max (3 500 € si compositeur = interprète). 10 jours de travail max.', null, 'Ouvert (commission janv. 2027)', true, '2026-12-21', 'Commissions mensuelles (voir onglet Calendrier). Prochaine : 25-29 janv. 2027, dépôt avant le 21/12/2026 inclus.', 'Dates postérieures à la commission. Minimums 120 € / 185 € bruts.', 'Dossier complet sur ADEL + contrat signé pour une date ferme postérieure à la commission. Solde du dossier précédent demandé avant tout nouveau dépôt.', 'Espace ADEL (adel.spedidam.fr)', 'https://www.spedidam.fr/aides-aux-projets/nos-programmes/aide-a-la-creation-dune-bande-originale-pour-le-spectacle-dramatique-ou-choregraphique/', null, null, 'https://www.monprojetmusique.fr/aides/bande-originale-pour-spectacle-dramatique-choregraphique-cirque-sons-et-lumieres-revue-cabaret-music-hall-ou-spectacle-de-marionnettes/', '2026-11-21', 'Claude (lecture du site officiel)', '2026-12-21', null),
  ('SPE-006', 'Spedidam', 'National', 'National', '{}'::text[], 'Aide à la promotion par l''image', 'Audiovisuel / promotion', 'Producteur de spectacle ou phonographique', 'Vidéo promotionnelle (EPK, pastille, interview, teaser). Hors documentaires et captations intégrales.', 'Plafond 2 500 €, max 80 % des frais de réalisation. Minorée de 20 % sans logo Spedidam.', 2500, 'Ouvert (commission janv. 2027)', true, '2026-12-21', 'Pas de dépôt API pour la commission de mai 2027.', 'Réalisation après la commission, dans les 6 mois ; mise en ligne au plus tard 3 mois après.', 'Document précisant les formats (EPK, teaser...). Feuille de présence Spedidam signée par les artistes enregistrés.', 'Espace ADEL (adel.spedidam.fr)', 'https://www.spedidam.fr/aides-aux-projets/nos-programmes/aide-a-la-promotion-par-limage/', null, null, 'https://www.monprojetmusique.fr/aides/promotion-par-limage/', '2026-11-21', 'Claude (lecture du site officiel)', '2026-12-21', null),
